package com.hbm.client.radar;
import com.hbm.client.model.LegacyItemTransforms;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.world.item.*;
/** Original small ItemRenderLibrary, large/source-provider and monitor/source-provider display matrices. */
public final class RadarItemRenderer extends BlockEntityWithoutLevelRenderer{private final int kind;public RadarItemRenderer(int kind){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());this.kind=kind;}@Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack p,MultiBufferSource buffers,int light,int overlay){p.pushPose();if(LegacyItemTransforms.isHeld(context))LegacyItemTransforms.held(p,context);else p.translate(.5,.5,.5);if(context==ItemDisplayContext.GUI){p.scale(1F/16,-1F/16,1F/16);p.translate(0,2,0);p.mulPose(Axis.XP.rotationDegrees(-30));p.mulPose(Axis.YP.rotationDegrees(45));p.scale(-1,-1,-1);p.translate(0,kind==0?-4:kind==1?-5:-3,0);float scale=kind==0?5:kind==1?3:5.5F;p.scale(scale,scale,scale);}else{boolean entity=context==ItemDisplayContext.GROUND||context==ItemDisplayContext.FIXED||context==ItemDisplayContext.NONE;if(entity)p.scale(1.5F,1.5F,1.5F);else p.translate(.5,.25,0);p.scale(.25F,.25F,.25F);if(context!=ItemDisplayContext.THIRD_PERSON_LEFT_HAND&&context!=ItemDisplayContext.THIRD_PERSON_RIGHT_HAND)p.mulPose(Axis.YP.rotationDegrees(90));}if(kind==2){p.translate(0,0,-.5);RadarDisplayRenderer.model(p,buffers,light,overlay);}else{if(kind==1){p.mulPose(Axis.YP.rotationDegrees(180));p.scale(.5F,.5F,.5F);}RadarRenderer.part(kind==1,kind==1?"radar_large":"radar_base",p,buffers,light,overlay,kind==1?"Radar":"Base");p.mulPose(Axis.YN.rotationDegrees(System.currentTimeMillis()%3600*.1F));if(kind==0)p.translate(-.125,0,0);RadarRenderer.part(kind==1,kind==1?"radar_large":"radar_dish",p,buffers,light,overlay,"Dish");}p.popPose();}}
